{"path": "/tmp/sv-58648c780a684d4786fed2dcf8a95692/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "@* Pagination controls: Previous, numbered pages, Next *@

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="GoToPrevious">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var pageNumber = i;
            <button class="btn-page @(pageNumber == CurrentPage ? "active" : "")"
                    @onclick="@(() => GoToPage(pageNumber))">
                @pageNumber
            </button>
        }

        <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="GoToNext">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }

    private async Task GoToPrevious() => await GoToPage(CurrentPage - 1);
    private async Task GoToNext() => await GoToPage(CurrentPage + 1);
}
"}

